Review this Android code for a turn-by-turn navigation screen and tell me what's wrong with it:

```kotlin
class NavigationActivity : AppCompatActivity() {
    private lateinit var mapboxNavigation: MapboxNavigation

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        mapboxNavigation = MapboxNavigationProvider.create(NavigationOptions.Builder(this).build())

        mapboxNavigation.registerRouteProgressObserver { routeProgress ->
            val distanceRemaining = routeProgress.navigationRoute.directionsRoute.legs()
                ?.mapNotNull { it.annotation()?.distance() ?: emptyList() }
                ?.flatten()
                ?.drop(routeProgress.currentRouteGeometryIndex)
                ?.fold(0.0) { a, b -> a + b } ?: 0.0

            distanceText.text = "${distanceRemaining.toInt()}m remaining"
        }

        mapboxNavigation.startTripSession()
    }

    override fun onDestroy() {
        super.onDestroy()
        MapboxNavigationProvider.destroy()
    }
}
```

